var CONFIG = {
  MIN_SCORE: 4,
  TOP_N: 10,
  DIVERSITY_CATEGORIES: ['politics','geopolitics','science','tech','economics','quirky'],
  MAX_AGE_HOURS: 24
};
return [{json: CONFIG}];

var config = $('Config').first().json;
var items = $input.all();
var now = new Date();
var maxAge = config.MAX_AGE_HOURS * 60 * 60 * 1000;
var minScore = config.MIN_SCORE;
var results = [];
for (var i = 0; i < items.length; i++) {
  var item = items[i].json;
  if (item._skip) continue;
  var pubDate = new Date(item.created_at || item.published_at || now);
  var age = now - pubDate;
  if (age > maxAge) continue;
  var score = parseFloat(item.composite_score) || 0;
  if (score < minScore) continue;
  results.push({ json: item });
}
results.sort(function(a, b) {
  return (parseFloat(b.json.composite_score) || 0) - (parseFloat(a.json.composite_score) || 0);
});
if (results.length === 0) {
  return [{ json: { _empty: true, message: 'No recent scored articles above threshold' } }];
}
return results;

var config = $('Config').first().json;
var items = $input.all();
var TOP_N = config.TOP_N;
var categories = config.DIVERSITY_CATEGORIES;
var now = new Date();

// Score each article
var scored = [];
for (var i = 0; i < items.length; i++) {
  var item = items[i].json;
  if (item._empty) continue;
  var meta = {};
  if (typeof item.metadata === 'string') {
    try { meta = JSON.parse(item.metadata); } catch(e) {}
  } else if (item.metadata) {
    meta = item.metadata;
  }
  var tags = meta.tags || {};
  var cluster = meta.cluster || null;
  var pubDate = new Date(item.published_at || item.ingested_at || now);
  var hoursOld = (now - pubDate) / (1000 * 60 * 60);
  var freshness = Math.max(0.1, 1 - hoursOld / 48);
  var sourceCount = parseInt(item.source_count) || 1;
  var compositeScore = parseFloat(item.composite_score) || 0;
  var curateScore = compositeScore * Math.log(sourceCount + 1) * freshness;
  scored.push({
    data: item,
    category: item.category || 'other',
    tags: tags,
    cluster: cluster,
    curateScore: curateScore
  });
}

// Sort by curateScore descending
scored.sort(function(a, b) { return b.curateScore - a.curateScore; });

// First pass: pick 1 per category
var selected = [];
var usedUrls = {};
var catCounts = {};
for (var c = 0; c < categories.length; c++) {
  catCounts[categories[c]] = 0;
}
for (var c = 0; c < categories.length; c++) {
  var cat = categories[c];
  for (var j = 0; j < scored.length; j++) {
    if (scored[j].category === cat && !usedUrls[scored[j].data.url]) {
      selected.push(scored[j]);
      usedUrls[scored[j].data.url] = true;
      catCounts[cat] = (catCounts[cat] || 0) + 1;
      break;
    }
  }
}

// Second pass: round-robin least-represented until TOP_N
while (selected.length < TOP_N && selected.length < scored.length) {
  var minCount = Infinity;
  var minCat = null;
  for (var c = 0; c < categories.length; c++) {
    var cnt = catCounts[categories[c]] || 0;
    if (cnt < minCount) { minCount = cnt; minCat = categories[c]; }
  }
  var found = false;
  for (var j = 0; j < scored.length; j++) {
    if (scored[j].category === minCat && !usedUrls[scored[j].data.url]) {
      selected.push(scored[j]);
      usedUrls[scored[j].data.url] = true;
      catCounts[minCat] = (catCounts[minCat] || 0) + 1;
      found = true;
      break;
    }
  }
  if (!found) {
    // Fill from any category
    for (var j = 0; j < scored.length; j++) {
      if (!usedUrls[scored[j].data.url]) {
        selected.push(scored[j]);
        usedUrls[scored[j].data.url] = true;
        var fc = scored[j].category;
        catCounts[fc] = (catCounts[fc] || 0) + 1;
        break;
      }
    }
    if (selected.length >= Object.keys(usedUrls).length || selected.length >= scored.length) break;
  }
}

// Re-sort final selection by curateScore
selected.sort(function(a, b) { return b.curateScore - a.curateScore; });

var results = [];
for (var i = 0; i < selected.length; i++) {
  var s = selected[i];
  var d = s.data;
  d._curate_score = s.curateScore;
  d._curate_rank = i + 1;
  d._tags = s.tags;
  d._cluster = s.cluster;
  results.push({ json: d });
}
if (results.length === 0) {
  return [{ json: { _empty: true, message: 'No articles passed curation' } }];
}
return results;

var items = $input.all();
var articles = [];
for (var i = 0; i < items.length; i++) {
  var item = items[i].json;
  if (item._empty) continue;
  var meta = {};
  if (typeof item.metadata === 'string') {
    try { meta = JSON.parse(item.metadata); } catch(e) {}
  } else if (item.metadata) {
    meta = item.metadata;
  }
  var tags = item._tags || meta.tags || {};
  articles.push({
    index: i,
    data: item,
    category: item.category || 'other',
    entities: Array.isArray(tags.entities) ? tags.entities : (typeof tags.entities === "string" ? [tags.entities] : []),
    topics: Array.isArray(tags.topics) ? tags.topics : (typeof tags.topics === "string" ? [tags.topics] : []),
    events: Array.isArray(tags.events) ? tags.events : (typeof tags.events === "string" ? [tags.events] : [])
  });
}

// Category distance map
var catGroups = {
  politics: 0, geopolitics: 0,
  science: 1, tech: 1,
  economics: 2,
  quirky: 3
};
var broadTerms = ['the','a','an','world','global','new','report','says','news','update','today'];

function countShared(a, b) {
  var count = 0;
  for (var i = 0; i < a.length; i++) {
    var val = (a[i] || '').toLowerCase();
    if (!val) continue;
    for (var j = 0; j < b.length; j++) {
      if (val === (b[j] || '').toLowerCase()) { count++; break; }
    }
  }
  return count;
}

function countBroad(arr) {
  var count = 0;
  for (var i = 0; i < arr.length; i++) {
    var val = (arr[i] || '').toLowerCase();
    for (var j = 0; j < broadTerms.length; j++) {
      if (val === broadTerms[j]) { count++; break; }
    }
  }
  return count;
}

var connections = [];
for (var i = 0; i < articles.length; i++) {
  for (var j = i + 1; j < articles.length; j++) {
    var a = articles[i];
    var b = articles[j];
    if (a.category === b.category) continue;
    var sharedEvents = countShared(a.events, b.events);
    var sharedTopics = countShared(a.topics, b.topics);
    var sharedEntities = countShared(a.entities, b.entities);
    if (sharedEvents === 0 && sharedTopics === 0 && sharedEntities === 0) continue;
    var broadPenalty = countBroad(a.topics) + countBroad(b.topics);
    var rawSignal = sharedEvents * 3.5 + sharedTopics * 2.5 + sharedEntities * 0.5 - broadPenalty * 2.0;
    var catA = catGroups[a.category] !== undefined ? catGroups[a.category] : 4;
    var catB = catGroups[b.category] !== undefined ? catGroups[b.category] : 4;
    var catDistance = Math.abs(catA - catB);
    var connectionScore = rawSignal * (1 + catDistance * 0.3);
    if (connectionScore >= 4) {
      connections.push({
        articleA: a.data.title,
        articleB: b.data.title,
        categoryA: a.category,
        categoryB: b.category,
        connectionScore: Math.round(connectionScore * 100) / 100,
        sharedEvents: sharedEvents,
        sharedTopics: sharedTopics,
        sharedEntities: sharedEntities
      });
    }
  }
}

// Attach connection flags to articles
var results = [];
for (var i = 0; i < articles.length; i++) {
  var d = articles[i].data;
  var myConns = [];
  for (var c = 0; c < connections.length; c++) {
    if (connections[c].articleA === d.title || connections[c].articleB === d.title) {
      myConns.push(connections[c]);
    }
  }
  d._cross_domain = myConns.length > 0;
  d._connections = myConns;
  results.push({ json: d });
}
if (results.length === 0) {
  return [{ json: { _empty: true, message: 'No articles for cross-domain' } }];
}
return results;

var items = $input.all();
var results = [];
for (var i = 0; i < items.length; i++) {
  var item = items[i].json;
  if (item._empty) continue;
  results.push({ json: { url: item.url } });
}
if (results.length === 0) {
  return [{ json: { _empty: true, message: 'No articles to update' } }];
}
return results;
